import org.jsoup.Connection;
import org.junit.Test;
import org.junit.Assert;
import org.mockito.Mockito;

import java.net.MalformedURLException;
import java.net.URL;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {

    @Test
    public void UrlBuilderNonNullUrlTest() {
        URL testUrl = null;
        try{
            testUrl = new URL("https://www.example.com");
        } catch (MalformedURLException e){
           // handle exception
        }

        UrlBuilder testBuilder = new UrlBuilder(testUrl);
        Assert.assertNotNull(testBuilder);
    }

    @Test
    public void buildSimpleUrlTest() {
        URL testUrl = null;
        try{
            testUrl = new URL("https://www.example.com");
        } catch (MalformedURLException e){
            // handle exception
        }

        UrlBuilder testBuilder = new UrlBuilder(testUrl);
        URL resultingUrl = testBuilder.build();

        Assert.assertEquals(testUrl, resultingUrl);
    }

    @Test
    public void appendKeyValValidKeyValTest() throws UnsupportedEncodingException {
        URL testUrl = null;
        try{
            testUrl = new URL("https://www.example.com");
        } catch (MalformedURLException e){
            // handle exception
        }

        UrlBuilder testBuilder = new UrlBuilder(testUrl);
        Connection.KeyVal kv = Mockito.mock(Connection.KeyVal.class);
        Mockito.when(kv.key()).thenReturn("testKey");
        Mockito.when(kv.value()).thenReturn("testValue");

        testBuilder.appendKeyVal(kv);
        URL resultingUrl = testBuilder.build();

        Assert.assertTrue(resultingUrl.toString().contains("testKey=testValue"));
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValUnsupportedEncodingExceptionTest() throws UnsupportedEncodingException {
        URL testUrl = null;
        try{
            testUrl = new URL("https://www.example.com");
        } catch (MalformedURLException e){
            // handle exception
        }

        UrlBuilder testBuilder = new UrlBuilder(testUrl);
        Connection.KeyVal kv = Mockito.mock(Connection.KeyVal.class);
        Mockito.when(kv.key()).thenReturn("testKey");
        Mockito.when(kv.value()).thenReturn("testValue\\U+1F435"); // illegal sequence for URLEncoder

        testBuilder.appendKeyVal(kv);
    }
}
